confident = {"cat": 0.99, "dog": 0.005, "rabbit": 0.005}
unsure    = {"cat": 0.4, "dog": 0.35, "rabbit": 0.25}

def decisiveness(d):
    return max(d.values())

print(decisiveness(confident))   # 0.99
print(decisiveness(unsure))      # 0.4

